import React from 'react';
import * as SeparatorPrimitive from '@radix-ui/react-separator';
import { styled } from '@hexa-ui/theme';
import { DividerTypes } from './DividerTypes';

const StyledDivider = styled(SeparatorPrimitive.Root, {
  backgroundColor: '$interfaceSurfaceSecondary',
  '&[data-orientation=horizontal]': {
    width: '100%',
    height: '0.0625rem',
  },
  '&[data-orientation=vertical]': {
    width: '0.0625rem',
    height: '100%',
  },
});

const Divider = ({
  orientation = 'horizontal',
  decorative = true,
  css,
  ...props
}: DividerTypes): JSX.Element => (
  <StyledDivider decorative={decorative} orientation={orientation} css={css} {...props} />
);

export default Divider;
